package main

import "fmt"

func MinMax(xs []int) (int, int) {
	lo, hi := xs[0], xs[0]
	for _, x := range xs {
		if x < lo {
			lo = x
		}
		if x > hi {
			hi = x
		}
	}
	return lo, hi
}

func main() {
	lo, hi := MinMax([]int{3, 1, 4, 1, 5})
	fmt.Println(lo, hi)
}
